                        "sla-pass-log-period": 10,
                        "sla": [
                            {
                                "id": 1,
                                "latency-threshold": 100,
                                "link-cost-factor": 1
                            }
                        ]
                    },
                    {
                        "name": "Internet",
                        "server": "8.8.8.8",
