                        "members": [
                            "1",
                            "2"
                        ],
                        "sla-fail-log-period": 10,
                        "sla-pass-log-period": 10,
                        "update-cascade-interface": 0,
                        "update-static-route": 0,
                        "sla": [
                            {
                                "id": 1,
                                "latency-threshold": 250,
                                "link-cost-factor": 1
                            }
                        ]
                    }
                ],
                "service": [
                    {
                        "id": 1,
                        "name": "Corporate",
                        "src": "CORP_LAN",
                        "dst": "CORP_LAN",
                        "protocol": 0,
                        "mode": 4,
                        "priority-members": [
                            "4",
                            "5",
                            "6",
                            "7",
                            "8",
                            "9"
                        ],
                        "sla": [
                            {
                                "health-check": "HUB",
                                "id": 1
                            }
                        ],
                        "tie-break": 3,
                        "role": 3,
                        "status": 1
                    }
                ]
            }
        }
    ]
